import { describe, it, expect, beforeEach } from '@jest/globals';
import request from 'supertest';
import express from 'express';

describe('Debug 404 Handler', () => {
  it('should test minimal express app 404', async () => {
    const app = express();
    
    // Add a simple route
    app.get('/api/exists', (req, res) => {
      res.json({ message: 'This exists' });
    });
    
    // Add 404 handler
    app.use((req, res) => {
      res.status(404).json({ error: 'Not found' });
    });
    
    // Test existing route
    const existsResponse = await request(app).get('/api/exists');
    expect(existsResponse.status).toBe(200);
    
    // Test non-existent route
    const notFoundResponse = await request(app).get('/api/nonexistent');
    expect(notFoundResponse.status).toBe(404);
  });
  
  it('should test actual app 404 behavior', async () => {
    // Import the actual app
    const appModule = await import('../../src/index');
    const app = appModule.app;
    
    // Test a non-existent route
    const response = await request(app).get('/api/nonexistent');
    
    console.log('Response status:', response.status);
    console.log('Response headers:', response.headers);
    console.log('Response body:', JSON.stringify(response.body, null, 2));
    
    // For now, just check what we're getting
    expect(response.status).toBeDefined();
  });
});